                "questionCode": "UW054",
                "questionType": "Boolean"
            },
            {
                "questionDescription": "هل تم رفض أو تأجيل أو سحب أو الموافقة بشروط خاصة على طلب إصدار وثيقة",
                "questionCode": "UW055",
                "questionType": "Boolean"
            },
            {
                "questionDescription": "هل لديك أي عقود تأمين أخرى مع شركات تأمين أخرى في دول مجلس التعاون الخليجي؟",
                "questionCode": "UW030",
                "questionType": "Boolean"
            }
        ]
    },
